cd /luxon && cat > tmp_dst_probe.js <<'EOF'
const { DateTime, Settings } = require("./src/luxon");
Settings.defaultZoneName = "America/New_York";

const cases = [
  ["1974-01-10T12:00", true],
  ["1974-06-01T12:00", true],
  ["1974-10-20T12:00", true],
  ["1974-01-03T12:00", false],
  ["1974-11-15T12:00", false],
  ["1974-12-01T12:00", false],
  ["2016-01-15T12:00", false],
  ["2016-06-15T12:00", true],
  ["2016-11-15T12:00", false],
  ["1974-01-06T03:00", true],
  ["1974-01-06T01:00", false],
];

let fails = 0;
for (const [iso, expected] of cases) {
  const dt = DateTime.fromISO(iso);
  const jan1 = dt.set({ month: 1, day: 1 }).offset;
  const jan = dt.set({ month: 1 }).offset;
  const may = dt.set({ month: 5 }).offset;
  const actual = dt.isInDST;
  const ok = actual === expected;
  if (!ok) fails++;
  console.log(
    `${ok ? "PASS" : "FAIL"} ${iso} offset=${dt.offset} jan1=${jan1} jan=${jan} may=${may} isInDST=${actual} expected=${expected}`
  );
}
console.log(fails === 0 ? "ALL PASS" : `${fails} FAILURES`);
EOF
