const { DateTime } = require("./src/luxon");
const zone = "America/New_York";

// Sweep all days of 1974 at noon
let bad = [];
for (let d = DateTime.fromObject({ year: 1974, month: 1, day: 1, zone });
     d.year === 1974;
     d = d.plus({ days: 1 })) {
  const inWindow = d >= DateTime.fromObject({ year: 1974, month: 1, day: 6, zone }) &&
                   d < DateTime.fromObject({ year: 1974, month: 10, day: 28, zone });
  if (d.isInDST !== inWindow) bad.push(d.toISODate() + " isInDST=" + d.isInDST + " expected=" + inWindow);
}
console.log("1974 daily sweep mismatches:", bad.length);
bad.slice(0, 10).forEach((b) => console.log("  " + b));

// Sweep 2016 too
bad = [];
for (let d = DateTime.fromObject({ year: 2016, month: 1, day: 1, zone });
     d.year === 2016;
     d = d.plus({ days: 1 })) {
  const inWindow = d >= DateTime.fromObject({ year: 2016, month: 3, day: 13, zone }) &&
                   d < DateTime.fromObject({ year: 2016, month: 11, day: 7, zone });
  if (d.isInDST !== inWindow) bad.push(d.toISODate() + " isInDST=" + d.isInDST + " expected=" + inWindow);
}
console.log("2016 daily sweep mismatches:", bad.length);
bad.slice(0, 10).forEach((b) => console.log("  " + b));

// Southern hemisphere sanity (Sydney): DST in Jan, not in Jul
const syd = (m, d) => DateTime.fromObject({ year: 2016, month: m, day: d, zone: "Australia/Sydney" });
console.log("Sydney Jan 15 isInDST:", syd(1, 15).isInDST, "(expect true)");
console.log("Sydney Jul 15 isInDST:", syd(7, 15).isInDST, "(expect false)");

// UTC / fixed offset
console.log("UTC isInDST:", DateTime.utc(2016, 6, 15).isInDST, "(expect false)");
EOF
