const units = ["years","quarters","months","weeks","days","hours","minutes","seconds","milliseconds"];
const H = 60*60*1000, D = 24*H;
const daysInYearAccurate = 146097.0/400, daysInMonthAccurate = 146097.0/4800;
const casual = { years:365*D, quarters:91*D, months:30*D, weeks:7*D, days:D, hours:H, minutes:60000, seconds:1000, milliseconds:1 };
const accurate = { years:daysInYearAccurate*D, quarters:(daysInYearAccurate/4)*D, months:daysInMonthAccurate*D, weeks:7*D, days:D, hours:H, minutes:60000, seconds:1000, milliseconds:1 };

const close = (a,b) => !Number.isNaN(a) && !Number.isNaN(b) && Math.abs(a-b) <= 1e-6*Math.max(1,Math.abs(b));
let bad = 0;

for (const [label, table, opts] of [["casual", casual, {}], ["accurate", accurate, {conversionAccuracy:"longterm"}]]) {
  for (const from of units) {
    for (const to of units) {
      if (from === to) continue;
      const d = Duration.fromObject(Object.assign({[from]:1}, opts));
      // 1) shiftTo
      const shifted = d.shiftTo(to).toObject();
      const got = (shifted[to]||0)*table[to];
      if (!close(got, table[from])) { bad++; console.log(`[${label}] SHIFT ${from}->${to}: expected ${table[from]/table[to]} ${to}, got`, JSON.stringify(shifted)); }
      // 2) normalize of the pair keeps both units, positive, correct total
      const norm = Duration.fromObject(Object.assign({[from]:1,[to]:1}, opts)).normalize().toObject();
      const total = units.reduce((s,u)=> s + (norm[u]||0)*table[u], 0);
      if (!close(total, table[from]+table[to])) { bad++; console.log(`[${label}] NORM {${from}:1,${to}:1}: expected total ${table[from]+table[to]}, got`, JSON.stringify(norm), "=", total); }
      for (const u of units) if (typeof norm[u] === "number" && norm[u] < 0) { bad++; console.log(`[${label}] NEG {${from}:1,${to}:1} -> ${u}=${norm[u]}`, JSON.stringify(norm)); break; }
      if (Object.keys(norm).some(u => norm[u] === null || Number.isNaN(norm[u]))) { bad++; console.log(`[${label}] NaN {${from}:1,${to}:1}`, JSON.stringify(norm)); }
      // 3) round-trip: as(to) of the pair equals (from+to) in to-units
      const asTo = Duration.fromObject(Object.assign({[from]:1,[to]:1}, opts)).as(to);
      if (!close(asTo*table[to], table[from]+table[to])) { bad++; console.log(`[${label}] AS {${from}:1,${to}:1}.as(${to}): expected ${(table[from]+table[to])/table[to]}, got ${asTo}`); }
    }
  }
}
// a few multi-unit cases
const multi = [
  [{years:2, days:5000}, {}, {years:15, days:255}],
  [{years:2, days:-2}, {}, {years:1, days:363}],
  [{years:-2, days:-5000}, {}, {years:-15, days:-255}],
  [{quarters:1, seconds:1}, {}, {quarters:1, seconds:1}],
  [{quarters:1, seconds:91*24*60*60}, {}, {quarters:2, seconds:0}],
  [{quarters:5, months:1, days:1}, {}, {quarters:5, months:1, days:1}],
  [{quarters:1, milliseconds:1}, {}, {quarters:1, milliseconds:1}]
];
for (const [input, opts, expected] of multi) {
  const got = Duration.fromObject(Object.assign({}, input, opts)).normalize().toObject();
  const ok = JSON.stringify(got) === JSON.stringify(expected);
  if (!ok) { bad++; console.log(`MULTI ${JSON.stringify(input)}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`); }
}
console.log(bad === 0 ? "ALL PAIRS OK" : `${bad} PROBLEMS`);
EOF
